      _ type: T.Type,
      from container: KeyedDecodingContainer<CodingKeys>,
      primary: CodingKeys,
      fallback: CodingKeys
  ) throws -> T {
      do {
          // return primary
      } catch let DecodingError.keyNotFound(key, _) where key.stringValue ==
  primary.stringValue {
          // return fallback
      } catch {
